import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

class Fish {
    String name;

    Fish(String name) {
        this.name = name;
    }

    public String toString() {
        return name;
    }
}

class ShortFirst implements Comparator<Fish> {
    public int compare(Fish a, Fish b) {
        return a.name.length() - b.name.length();
    }
}

public class Main {
    public static void main(String[] args) {
        List<Fish> pond = new ArrayList<>();
        pond.add(new Fish("{n1}"));
        pond.add(new Fish("{n2}"));
        pond.add(new Fish("{n3}"));

        pond.sort(new ShortFirst());
        System.out.println(pond);
    }
}
